import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const root='docs/development/raid-production-release',out=root+'/bundle',old='docs/development/raid-production-preparation/bundle';fs.mkdirSync(out,{recursive:true});
const read=p=>fs.readFileSync(p,'utf8'),json=p=>JSON.parse(read(p)),q=s=>"'"+s.replaceAll("'","''")+"'",hash=s=>createHash('sha256').update(s).digest('hex');
const drift=json(root+'/drift.json');assert.deepEqual(drift.changed.map(x=>x.name),['kpi_daily_engagement_v1','refresh_kpi_overview_saved_results']);assert.equal(drift.removed.length,0);assert.deepEqual(drift.newMigrations,[{name:'kpi_social_active_raid_point_daily',version:'20260909151723'}]);
const pat=read(path.join(os.homedir(),'.supabase/access-token')).trim();
const sql=read(old+'/00-readonly-recheck.sql').replace(/ is not distinct from '[a-f0-9]+' as matches/g,' as hash');
const r=await fetch('https://api.supabase.com/v1/projects/ktpolnkyyfkowxdmijww/database/query',{method:'POST',headers:{Authorization:`Bearer ${pat}`,'Content-Type':'application/json'},body:JSON.stringify({query:sql})});assert.ok(r.ok);const hashes=(await r.json())[0].checks;fs.writeFileSync(root+'/baseline-hashes.json',JSON.stringify(hashes,null,2));
let guard=read(old+'/00-baseline-guard.sql');
guard=guard.replace('f4015bd5da10bae06204565726765eac',hashes.find(x=>x.check_name==='public function body/signature/owner/ACL').hash).replace('8afe7af54d5c7870a687c74152ec8dfa',hashes.find(x=>x.check_name==='migration history').hash);
fs.writeFileSync(out+'/00-baseline-guard.sql','-- Reviewed KPI-only drift: drift.json. Every other baseline guard is unchanged.\n'+guard);
for(const file of ['01-snapshot-dependency.sql','02-raid-delta.sql','03-expiry-cron.sql','05-stop-new-operations.sql'])fs.copyFileSync(old+'/'+file,out+'/'+file);
let post=read(old+'/04-postflight.sql').replace('7e86ab7e3b15594247190eb49035d63c','103e6b634a4db1da6ca6e7d870dd63c6');
const migrations=json(root+'/catalog-before.json')[0].audit.migrations;
post=post.replace(/if \(select jsonb_agg\(t order by version\)[^\n]+then raise exception 'migration history changed'; end if;/,`if (select jsonb_agg(t order by version) from (select version,name from supabase_migrations.schema_migrations)t) is distinct from ${q(JSON.stringify(migrations))}::jsonb then raise exception 'migration history changed'; end if;`);
post+=`\ndo $kpi$ begin if not exists(select from pg_proc where oid=to_regprocedure('public.kpi_daily_engagement_v1(date,date)') and md5(pg_get_functiondef(oid))='e5da97325d85412cccc4d894e57140be' and proacl::text='{postgres=X/postgres}') then raise exception 'KPI daily function changed';end if;end $kpi$;\n`;
fs.writeFileSync(out+'/04-postflight.sql',post);
for(const file of ['06-launch-balance.sql','07-launch-postflight.sql'])fs.copyFileSync('docs/development/raid-launch-integration/bundle/'+file,out+'/'+file);
const proposal=json('docs/development/raid-launch-integration/proposed-settings-v3.json');
const approved={candidate:'c844534f5ce160fb3e713a58aed8377190aaa209',status:'USER_APPROVED',humanAcceptance:'User replied 問題ありません to fixed Preview integrated acceptance request',difficulties:proposal.difficulties.map(p=>({id:p.id,clearDamageExclusive:p.clear.minimumContributionDamage,rescueMinimumBattles:p.rescue.minimumBattles,rescueDamageInclusive:p.rescue.minimumContributionDamage,clearItems:p.clear.items,rescueItems:p.rescue.items})),bothRequireDefeat:true,preserveEligibilityWindowAndIdempotency:true,attributeTimes2:false,guildTimes2:false};
fs.writeFileSync(root+'/approved-settings.json',JSON.stringify(approved,null,2));
let settings=`-- User-approved public rules. No QA fixture or account mutation. Run in caller transaction.\ndo $guard$ begin if exists(select from raid_room_creation_settings where enabled) or exists(select from raid_room_battle_settings where enabled) or exists(select from raid_room_rescue_settings where enabled) then raise exception 'Already open; review applied state';end if;if exists(select from raid_room_clear_reward_items) or exists(select from raid_room_rescue_reward_items) then raise exception 'Existing reward items; do not overwrite';end if;end $guard$;\n`;
for(const p of approved.difficulties){settings+=`update public.raid_room_difficulty_rules set rescue_min_battles=${p.rescueMinimumBattles},rescue_min_contribution_damage=${p.rescueDamageInclusive} where difficulty=${q(p.id)};\nupdate public.raid_room_clear_reward_rules set enabled=true,minimum_contribution_damage=${p.clearDamageExclusive} where difficulty=${q(p.id)};\nupdate public.raid_room_rescue_reward_rules set enabled=true where difficulty=${q(p.id)};\n`;for(const item of p.clearItems)settings+=`insert into public.raid_room_clear_reward_items(difficulty,item_id,quantity) values(${q(p.id)},${q(item.itemId)},${item.quantity});\n`;for(const item of p.rescueItems)settings+=`insert into public.raid_room_rescue_reward_items(difficulty,item_id,quantity) values(${q(p.id)},${q(item.itemId)},${item.quantity});\n`;}
settings+=`do $check$ begin if (select count(*) from raid_room_clear_reward_items)<>4 or (select count(*) from raid_room_rescue_reward_items)<>4 or (select count(*) from raid_room_clear_reward_rules where enabled)<>4 or (select count(*) from raid_room_rescue_reward_rules where enabled)<>4 then raise exception 'Public reward incomplete';end if;end $check$;\n`;
fs.writeFileSync(out+'/08-approved-settings.sql',settings);
fs.writeFileSync(out+'/09-open-operations.sql',`-- Execute only after compatible Edge, Cron and frontend checks.\nupdate public.raid_legacy_settings set enabled=false where singleton;\nupdate public.raid_room_creation_settings set enabled=true where singleton;\nupdate public.raid_room_battle_settings set enabled=true where singleton;\nupdate public.raid_room_rescue_settings set enabled=true where singleton;\ndo $check$ begin if (select count(*) from raid_room_creation_settings where singleton and enabled)<>1 or (select count(*) from raid_room_battle_settings where singleton and enabled)<>1 or (select count(*) from raid_room_rescue_settings where singleton and enabled)<>1 or (select count(*) from raid_legacy_settings where singleton and not enabled)<>1 then raise exception 'Operation flags invalid';end if;end $check$;\n`);
const files=['00-baseline-guard.sql','01-snapshot-dependency.sql','02-raid-delta.sql','04-postflight.sql','06-launch-balance.sql','07-launch-postflight.sql'];
fs.writeFileSync(out+'/apply-db.sql',`begin;set local statement_timeout='60s';set local lock_timeout='2s';set local search_path=public,pg_catalog;\n`+files.map(f=>read(out+'/'+f)).join('\n')+`\nnotify pgrst,'reload schema';commit;\n`);
const manifest={candidate:approved.candidate,reviewedDrift:drift,dbOrder:files,files:fs.readdirSync(out).sort().map(file=>({file,sha256:hash(fs.readFileSync(out+'/'+file))}))};fs.writeFileSync(root+'/bundle-manifest.json',JSON.stringify(manifest,null,2));console.log(JSON.stringify({files:manifest.files.length,settings:'APPROVED',kpiDrift:'2 functions + 1 migration preserved'}));
